insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_115_v1'
from (values
('127.818.d.1.A',3,'A second-year machining student compares the degrees, apprenticeships and NIMS credentials that lead to a CNC programmer job and notes the algebra and geometry she still needs. She is determining:','["academic knowledge and skills required for postsecondary education and careers", "only her lunch choices", "only the shop''s color", "only her weekend plans"]'::jsonb,0,'Know the requirements before choosing a path.','original'),
('127.818.d.1.A',4,'A student planning a career in CNC programming should take courses in:','["only choir", "math, drafting and computer applications", "only cooking", "only art history"]'::jsonb,1,'CNC careers rely on these skills.','original'),
('127.818.d.1.B',3,'A shop owner explains that customers expect on-time delivery, parts to print and quick answers when a problem arises. Meeting these expectations helps to:','["reduce orders", "raise complaints", "foster positive customer satisfaction", "lose repeat customers"]'::jsonb,2,'Employer expectations support customer satisfaction.','original'),
('127.818.d.1.B',4,'A machinist who finds that a batch will be late should:','["hide the delay", "blame the customer", "ship it without notice", "tell the supervisor right away so the customer can be notified"]'::jsonb,3,'Early communication preserves trust.','original'),
('127.818.d.1.C',3,'A student practices a mock job interview, completes an application and writes a resume listing her NIMS credentials. She is demonstrating standards required in the workplace such as:','["interviewing, completing applications and resume writing", "only sleeping", "only texting", "only gaming"]'::jsonb,0,'Hiring steps follow standards.','original'),
('127.818.d.1.C',4,'A good resume for a machinist apprenticeship should list:','["only her nickname", "skills, training and relevant projects or credentials", "only favorite shows", "only her age"]'::jsonb,1,'A resume shows qualifications.','original'),
('127.818.d.1.D',3,'Each semester a student checks which NIMS credentials she has earned against the list she set in ninth grade and updates her plan. She is evaluating:','["a menu", "a score", "progress toward personal career goals", "a dance"]'::jsonb,2,'Review progress against goals.','original'),
('127.818.d.1.D',4,'Reviewing progress toward a career goal helps a student:','["forget the goal", "avoid planning", "skip steps", "adjust the plan and stay on track"]'::jsonb,3,'Progress checks guide corrections.','original'),
('127.818.d.1.E',3,'A machinist confirms the revision letter on a print with the engineer by email before cutting a batch. She is communicating to:','["clarify objectives and expectations in the workplace", "confuse the engineer", "avoid work", "slow the batch down"]'::jsonb,0,'Confirm requirements before production.','original'),
('127.818.d.1.E',4,'When a print revision is unclear, the machinist should:','["skip the part", "ask the engineer or supervisor before cutting", "use the older print", "guess which is right"]'::jsonb,1,'Ask before cutting.','original'),
('127.818.d.1.F',3,'A CNC shop posts its lockout/tagout procedure, requires hearing protection near the loud saws and keeps safety data sheets handy. These show skills related to:','["company logos", "shift bidding", "health and safety in the workplace as specified by OSHA", "office decorating"]'::jsonb,2,'OSHA rules protect workers.','original'),
('127.818.d.1.F',4,'A technician is about to clear a jam inside a CNC cell. To keep anyone from restarting the equipment while her hands are inside, she should:','["ask a coworker to watch the start button", "turn the lights off", "slow the feed rate", "apply her own lock and tag to the energy source"]'::jsonb,3,'Personal lockout/tagout controls hazardous energy.','original'),
('127.818.d.2.A',3,'A machinist uses tables in the handbook to find the tap drill for a 5/16-18 thread and the allowance for a class 2 fit. She is applying:','["technical aspects found in The Machinery''s Handbook", "a sports almanac", "a dictionary of slang", "a recipe book"]'::jsonb,0,'The handbook provides threads and fits data.','original'),
('127.818.d.2.A',4,'A machinist needs the minor diameter of a standard thread. The best source is:','["a cookbook", "The Machinery''s Handbook", "a magazine", "a novel"]'::jsonb,1,'Thread data is in the handbook.','original'),
('127.818.d.2.B',3,'A student searches a tooling supplier''s website for insert recommendations and checks the source is a reputable manufacturer. She is selecting:','["only social media", "random pages", "appropriate Internet resources as applied to manufacturing", "unknown ads"]'::jsonb,2,'Use reliable resources.','original'),
('127.818.d.2.B',4,'A reliable Internet source for the cutting speed of a particular insert grade is:','["a game forum", "an unrelated blog", "an anonymous comment", "the insert manufacturer''s technical page"]'::jsonb,3,'Manufacturer data is most reliable.','original'),
('127.818.d.3.A',3,'A student programs and turns a multi-diameter shaft with a groove and a thread to NIMS Level 1 print dimensions. She is developing:','["a detailed turning part such as the NIMS Level 1 turning project", "a sculpture", "a recipe", "a poster"]'::jsonb,0,'NIMS turning project practice.','original'),
('127.818.d.3.A',4,'The NIMS credential is useful to a machinist because it:','["reduces pay", "proves skills against an industry standard", "hides skills", "replaces work"]'::jsonb,1,'Industry-recognized credential.','original'),
('127.818.d.3.B',3,'A student mills a plate with a pocket, a bolt-hole pattern and a contour to NIMS Level 1 print dimensions and inspects each feature. She is developing:','["a poster", "a poem", "a detailed milling part such as the NIMS Level 1 milling part", "a quilt"]'::jsonb,2,'NIMS milling project practice.','original'),
('127.818.d.3.B',4,'A NIMS-style milling project is graded mainly on:','["the student''s nickname", "how fast it cools", "how it looks in a photo", "how closely the part matches the print tolerances"]'::jsonb,3,'Accuracy to print matters.','original'),
('127.818.d.4.A',3,'A student researches how punched tape and early servo controls led to modern computer-controlled machines. She is researching:','["the history of numerical control machines", "the history of dance", "the history of cooking", "the history of painting"]'::jsonb,0,'NC history leads to CNC.','original'),
('127.818.d.4.A',4,'Early numerical control machines were commonly programmed using:','["voice commands", "punched tape", "the cloud", "touch screens"]'::jsonb,1,'Tape preceded computers.','original'),
('127.818.d.4.B',3,'A class tours a plant and sees a 2-axis lathe, a 3-axis vertical mill, a wire EDM and a laser cutter all running programs. They are distinguishing among:','["kinds of pottery", "types of fruit", "different types of CNC machines used in industry", "sports teams"]'::jsonb,2,'CNC includes many machine types.','original'),
('127.818.d.4.B',4,'A wire EDM machine is used to:','["bake dough", "print paper", "dye fabric", "cut hard metals using electrical sparks and a wire"]'::jsonb,3,'EDM erodes metal electrically.','original'),
('127.818.d.4.C',3,'A new CNC operator learns to keep the door closed while running, to know where the emergency stop is and to never reach into a moving machine. She is demonstrating:','["safety rules for CNC operation", "shortcuts", "guesses", "games"]'::jsonb,0,'CNC safety rules protect operators.','original'),
('127.818.d.4.C',4,'If something unexpected happens on a running CNC machine, the operator should first:','["open the door and watch", "press the emergency stop", "turn up the feed", "reach in to fix it"]'::jsonb,1,'E-stop halts motion.','original'),
('127.818.d.4.D',3,'A student types a program at the control, loads another from a USB drive and receives a third through a network from the CAM station. She is demonstrating:','["methods of watering plants", "methods of sharpening pencils", "the methods by which programs can be entered into a control", "methods of folding paper"]'::jsonb,2,'Programs can be entered several ways.','original'),
('127.818.d.4.D',4,'One way to enter a CNC program at the machine is:','["knocking on the door", "mailing a letter", "painting the control", "manual data input (MDI)"]'::jsonb,3,'MDI types commands at the control.','original'),
('127.818.d.4.E',3,'A student labels a drawing with the terms spindle, turret, work offset, feed rate and G-code to build her shop vocabulary. She is using:','["appropriate machining terminology to enhance CNC vocabulary", "slang from games", "random words", "only nicknames"]'::jsonb,0,'Correct terms prevent mistakes.','original'),
('127.818.d.4.E',4,'The rate at which the cutter or workpiece advances during cutting is the:','["tool offset", "feed rate", "work zero", "spindle speed"]'::jsonb,1,'Feed rate = travel per time or per revolution.','original'),
('127.818.d.5.A',3,'A student studies the servo motors and ball screws that move the axes of a CNC mill and how the stepper motors on a small router differ. She is examining:','["kinds of kitchen mixers", "types of fans", "the types of drive motors used on CNC machinery", "sets of speakers"]'::jsonb,2,'Servo and stepper drives move axes.','original'),
('127.818.d.5.A',4,'Compared with stepper motors, servo motors on a CNC machine typically provide:','["less torque control", "lower precision", "no feedback", "feedback for closed-loop position control"]'::jsonb,3,'Servos use encoders.','original'),
('127.818.d.5.B',3,'A student explains that every point on a flat part can be located by an X distance and a Y distance from the origin and shows it on a graph. She is explaining:','["the Cartesian coordinate system", "the solar system", "the metric system", "the time zone system"]'::jsonb,0,'Cartesian coordinates use axes from an origin.','original'),
('127.818.d.5.B',4,'On a CNC mill, the point at coordinates X2, Y3 lies:','["at the origin", "2 units along X and 3 units along Y from the origin", "3 units along X and 2 along Y", "2 units below the origin"]'::jsonb,1,'X first, then Y.','original'),
('127.818.d.5.C',3,'A programmer compares one program that moves to X1.0, X2.5, X4.0 from the origin and another that moves 1.0, 1.5, 1.5 from each last position. She is differentiating between:','["big and small", "hot and cold", "absolute and incremental positioning", "fast and slow"]'::jsonb,2,'Absolute vs incremental.','original'),
('127.818.d.5.C',4,'In incremental positioning, each move is measured from:','["the program start only", "the part''s end only", "the machine''s home only", "the tool''s current position"]'::jsonb,3,'Incremental uses the last position.','original'),
('127.818.d.5.D',3,'On a print, one drawing gives every dimension from a single edge and another gives each dimension from the previous feature. The student is illustrating the difference between:','["datum and delta dimensioning", "front and back", "color and shade", "price and cost"]'::jsonb,0,'Datum vs delta (chain) dimensioning.','original'),
('127.818.d.5.D',4,'A benefit of datum dimensioning is that:','["it adds errors", "errors do not stack from one feature to the next", "it uses more paper", "it is harder to read"]'::jsonb,1,'Each feature is located from the same datum.','original'),
('127.818.d.6.A',3,'A student writes out which tools, speeds, feeds and cutting order she will use to machine an aluminum bracket and then labels each operation. She is developing:','["a budget plan", "a vacation plan", "a detailed process plan including tool selection, feeds and speeds", "a party plan"]'::jsonb,2,'A process plan guides CNC programming.','original'),
('127.818.d.6.A',4,'A detailed CNC process plan should be completed:','["after machining", "after shipping", "after inspection", "before writing the program"]'::jsonb,3,'Plan first, then program.','original'),
('127.818.d.6.B',3,'A student arranges the operations so that roughing comes before finishing and plans in-process checks of the critical bore. She is developing:','["a logical sequence of operations and appropriate inspection points", "an alphabetical list", "a color chart", "a random list"]'::jsonb,0,'Sequence and inspection planning.','original'),
('127.818.d.6.B',4,'Roughing cuts are usually done before finishing cuts because:','["they are quieter", "they remove most material and leave stock for the final pass", "they take no time", "they use less power"]'::jsonb,1,'Rough then finish.','original'),
('127.818.d.6.C',3,'A student mounts a triangular carbide insert on a holder, tightens the screw and runs a turning pass. She is demonstrating the use of:','["paper tips", "wooden blades", "carbide inserts", "rubber tips"]'::jsonb,2,'Carbide inserts are common cutting tools.','original'),
('127.818.d.6.C',4,'A key advantage of carbide inserts is that they:','["cost nothing", "melt easily", "dull instantly", "stay hard at high cutting speeds"]'::jsonb,3,'Carbide resists heat.','original'),
('127.818.d.6.D',3,'A machinist chooses an insert''s shape, grade, nose radius and coating after checking the catalog for the material to be cut. She is applying:','["carbide inserts by determining the correct type, grade and geometry", "no insert", "only the cheapest", "random inserts"]'::jsonb,0,'Match the insert to the job.','original'),
('127.818.d.6.D',4,'A larger nose radius on a turning insert generally gives:','["a weaker tip", "a stronger tip but more cutting pressure", "no cutting", "no change"]'::jsonb,1,'Larger radius = stronger, more pressure.','original'),
('127.818.d.7.A',3,'A student swaps from a drill to a 1/2-inch end mill to a face mill by hand and by using the machine''s automatic changer. She is performing:','["wardrobe changes", "channel changes", "various types of tool changes", "station changes"]'::jsonb,2,'Tool changes are manual or automatic.','original'),
('127.818.d.7.A',4,'Before changing a tool manually on a CNC mill, the operator should first:','["open the guard during a cut", "remove the tool during cutting", "reach in while it spins", "stop the spindle and make sure the machine is in a safe state"]'::jsonb,3,'Safe state first.','original'),
('127.818.d.7.B',3,'A class installs collet-style tool holders that can be exchanged in the spindle in seconds without re-measuring each tool. They are demonstrating:','["quick change tooling used on CNC milling machines", "glued tooling", "hand-cranked tooling", "slow tooling"]'::jsonb,0,'Quick-change tooling saves time.','original'),
('127.818.d.7.B',4,'Quick-change tooling reduces:','["machine height", "setup time", "part size", "spindle speed"]'::jsonb,1,'It speeds tool swaps.','original'),
('127.818.d.7.C',3,'After use, a student wipes each tool holder and returns it to its labeled slot on a rack so cutters are not chipped and are easy to find. She is demonstrating:','["careless handling", "leaving tools on the table", "appropriate tool storage", "random storage"]'::jsonb,2,'Good storage protects tools.','original'),
('127.818.d.7.C',4,'Cutting tools are stored in racks or drawers so that cutting edges:','["knock together", "get dirty", "are exposed", "are protected from damage"]'::jsonb,3,'Protected edges stay sharp.','original'),
('127.818.d.7.D',3,'A student enters the length of a 3/8-inch end mill into the tool-offset table so the control knows where its tip is relative to the part. She is demonstrating the use of:','["tool offset registers", "paint colors", "random numbers", "clock settings"]'::jsonb,0,'Offset registers store tool data.','original'),
('127.818.d.7.D',4,'A tool length offset tells the control:','["the time of day", "how far the tool tip extends from the spindle", "the shop''s address", "the part''s color"]'::jsonb,1,'Offsets give tool geometry.','original'),
('127.818.d.7.E',3,'A student touches off a tool on the part''s surface and records the Z value to find that tool''s length offset. She is determining:','["a travel distance", "a quilt length", "tool offset length", "a recipe amount"]'::jsonb,2,'Touch-off measures length offset.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_115_v1'
from (values
('127.818.d.7.E',4,'To measure a tool''s length offset, an operator commonly:','["measures the tool''s color", "paints the tool", "weighs the tool", "touches the tool to a known surface and records the Z position"]'::jsonb,3,'Touch-off or presetter.','original'),
('127.818.d.7.F',3,'A student enters work and tool offsets for each of three tools and runs a first part to confirm the dimensions. She is incorporating:','["tool offsets for a setup", "dates for a calendar", "songs for a playlist", "colors for a quilt"]'::jsonb,0,'Offsets are part of setup.','original'),
('127.818.d.7.F',4,'After entering offsets for a new setup, the operator should:','["run at full speed unwatched", "run the first part carefully and verify its dimensions", "skip inspection", "leave without checking"]'::jsonb,1,'Prove out the setup.','original'),
('127.818.d.8.A',3,'Before running a CNC lathe, a student closes the chuck guard, checks that the jaws are tight on the bar and keeps the door interlock working. She is using:','["equipment carelessly", "equipment without guards", "equipment commonly associated with a CNC lathe in a safe manner", "equipment with the door open"]'::jsonb,2,'CNC lathe safety.','original'),
('127.818.d.8.A',4,'The chuck pressure on a CNC lathe is checked so that the workpiece:','["looks better", "runs hotter", "turns slower", "does not come loose at spindle speed"]'::jsonb,3,'Insufficient grip is a hazard.','original'),
('127.818.d.8.B',3,'A student points to the spindle, chuck, turret, tailstock and operator panel on a CNC lathe and explains what each does. She is recognizing, naming and describing:','["the primary components of a CNC lathe", "parts of a guitar", "parts of a loom", "parts of a bicycle"]'::jsonb,0,'Know lathe components.','original'),
('127.818.d.8.B',4,'On a CNC lathe, the turret is the component that:','["holds the chips", "holds several tools and indexes the right one into position", "displays the program", "cools the spindle"]'::jsonb,1,'Turrets carry tools.','original'),
('127.818.d.8.C',3,'At the start of each shift a student checks the way lube level, the hydraulic pressure and the air pressure on the CNC lathe. She is performing:','["a paint job", "a lunch order", "preventative maintenance checks on a CNC lathe", "a shop tour"]'::jsonb,2,'PM checks prevent downtime.','original'),
('127.818.d.8.C',4,'Checking the way lube on a CNC lathe each day helps to:','["hide leaks", "raise noise", "slow the spindle", "prevent wear and keep the slides moving smoothly"]'::jsonb,3,'Lubrication reduces wear.','original'),
('127.818.d.8.D',3,'A student uses a refractometer to check the coolant mix on the lathe and adds concentrate when the reading is low. She is testing:','["the coolant for proper density and adjusting it", "the tea for sweetness", "the paint for color", "the soda for flavor"]'::jsonb,0,'Coolant concentration matters.','original'),
('127.818.d.8.D',4,'A tool used to measure the concentration of water-soluble coolant is a:','["plumb bob", "refractometer", "level", "micrometer"]'::jsonb,1,'Refractometers read concentration.','original'),
('127.818.d.8.E',3,'The operator turns on the main disconnect, presses the power button and waits for the control to boot before homing the axes. She is performing:','["a lunch break", "a restart of a laptop only", "a power up on a standard CNC lathe", "a shutdown"]'::jsonb,2,'Power-up sequence.','original'),
('127.818.d.8.E',4,'After a CNC lathe is powered on, the operator typically needs to:','["remove the guards", "disable the stop", "load the coolant", "home the axes before running a program"]'::jsonb,3,'Homing sets a reference.','original'),
('127.818.d.8.F',3,'A student uses the handwheel and jog keys to move the turret toward the part in small steps until it nearly touches the stock. She is demonstrating:','["the use of jog controls on the operator panel of a CNC lathe", "a dance", "a puzzle", "a drawing"]'::jsonb,0,'Jog controls move axes manually.','original'),
('127.818.d.8.F',4,'When jogging a tool close to a part, the operator should use:','["maximum rapid", "a slow jog speed or small handwheel increments", "closed eyes", "no guard"]'::jsonb,1,'Slow near the work.','original'),
('127.818.d.8.G',3,'A student assembles a boring bar in its holder, sets the stickout and measures it on a presetter before loading it into the turret. She is demonstrating the ability to:','["hide tools", "paint tools", "locate, assemble and measure tooling for a CNC lathe", "throw tools"]'::jsonb,2,'Tool preparation.','original'),
('127.818.d.8.G',4,'The stickout of a boring bar is kept short because a long overhang:','["makes it quiet", "increases rigidity", "makes it cool", "can cause chatter and poor accuracy"]'::jsonb,3,'Overhang reduces stiffness.','original'),
('127.818.d.8.H',3,'A student loads each turned-part tool into its numbered turret pocket to match the tool list in the program. She is:','["installing tools and holders in the automatic tool changer locations of a CNC lathe", "cleaning the floor", "oiling the chuck", "painting the turret"]'::jsonb,0,'Tool numbers must match the program.','original'),
('127.818.d.8.H',4,'If a tool is placed in the wrong turret position, the machine may:','["run cooler", "use the wrong tool and crash", "run quieter", "skip the program"]'::jsonb,1,'Tool position must match.','original'),
('127.818.d.8.I',3,'A student touches the tool to the face of the bar stock and sets that Z position as the part''s face zero on the lathe. She is:','["setting a clock", "setting a timer", "locating and setting the workpiece to zero on a CNC lathe", "setting a table"]'::jsonb,2,'Z zero is commonly the part face.','original'),
('127.818.d.8.I',4,'On many CNC lathe programs, the Z zero is set at:','["the tailstock", "the ceiling", "the chip pan", "the finished face of the part"]'::jsonb,3,'Face zero is common.','original'),
('127.818.d.8.J',3,'After touching off, the student enters the work offset in G54 so the program references the part instead of the machine origin. She is setting:','["work offsets for the part to be machined", "wall offsets", "pay offsets", "rent offsets"]'::jsonb,0,'Work offsets locate the part.','original'),
('127.818.d.8.J',4,'A work offset such as G54 tells the control:','["when to stop for lunch", "where the part''s zero is relative to the machine", "how many workers are present", "what color the part is"]'::jsonb,1,'G54 stores part zero.','original'),
('127.818.d.8.K',3,'For each turning, boring and threading tool in the turret, the student enters the X and Z geometry values that the control uses to place the tool tip. She is setting:','["a quilt", "a poem", "the proper geometry/tool offsets for each tool in a standard tool turret", "a recipe"]'::jsonb,2,'Geometry offsets are per tool.','original'),
('127.818.d.8.K',4,'If a tool''s offset is entered incorrectly, the finished part will most likely:','["be lighter", "be painted", "be quieter", "have the wrong size or the tool may crash"]'::jsonb,3,'Wrong offset = wrong dimension.','original'),
('127.818.d.8.L',3,'After proving out the program in single-block mode, the operator presses cycle start and lets the lathe run through all the operations by itself. She is operating:','["a CNC lathe in automatic mode", "a tablet", "a toaster", "a printer"]'::jsonb,0,'Automatic mode runs the program.','original'),
('127.818.d.8.L',4,'While a CNC lathe runs in automatic mode, the operator should:','["remove the guard", "stay at the machine and watch for problems", "open the door", "leave for the day"]'::jsonb,1,'Monitor the cycle.','original'),
('127.818.d.8.M',3,'At the end of the shift, the student retracts the turret, cleans the chips, presses the power-off button and flips the main disconnect. She is illustrating:','["the power up", "a restart", "the proper power down process on a CNC lathe", "a resume"]'::jsonb,2,'Shutdown sequence.','original'),
('127.818.d.8.M',4,'Before powering down a CNC lathe, the operator should first:','["leave chips in place", "cut the main power at once", "unplug it mid-cut", "return the axes to a safe position and clean the machine"]'::jsonb,3,'Park and clean.','original'),
('127.818.d.9.A',3,'A student checks that the vise is tight, the spindle is stopped and the enclosure door is closed before pressing cycle start on a CNC mill. She is using:','["equipment commonly found on and around a CNC mill in a safe manner", "equipment with the door open", "equipment carelessly", "equipment without goggles"]'::jsonb,0,'CNC mill safety.','original'),
('127.818.d.9.A',4,'Before starting a CNC mill program, the operator should confirm that the:','["vise is loose", "workholding is secure and the area is clear", "tools are missing", "door is open"]'::jsonb,1,'Secure before starting.','original'),
('127.818.d.9.B',3,'A student points to the column, table, spindle, tool changer and control on a vertical machining center and explains each. She is recognizing, naming and describing:','["parts of a stove", "parts of a bicycle", "the primary components of a CNC mill", "parts of a phone"]'::jsonb,2,'Mill components.','original'),
('127.818.d.9.B',4,'On a CNC mill, the automatic tool changer is the component that:','["holds paper", "clears chips only", "cools the part", "swaps tools in and out of the spindle during a program"]'::jsonb,3,'ATCs swap tools automatically.','original'),
('127.818.d.9.C',3,'Before a mill job, an operator checks the oil in the way lubrication reservoir, the air pressure and the spindle taper for chips. She is performing:','["preventative maintenance checks on a CNC mill", "a paint check", "a menu check", "a grade check"]'::jsonb,0,'PM keeps machines accurate.','original'),
('127.818.d.9.C',4,'Keeping the spindle taper clean on a CNC mill helps to:','["add noise", "hold the tool holder accurately", "speed rust", "reduce power"]'::jsonb,1,'A clean taper seats tools.','original'),
('127.818.d.9.D',3,'A student dips a test strip into the coolant tank on a CNC mill to read its pH and concentration and adjusts the mix. She is testing:','["the juice for sugar", "the milk for taste", "the coolant for proper density and adjusting it", "the water for chlorine"]'::jsonb,2,'Coolant concentration affects tool life.','original'),
('127.818.d.9.D',4,'Coolant that is too weak in concentration can cause:','["better finish", "longer tool life", "less rust", "rust and shorter tool life"]'::jsonb,3,'Weak coolant fails to protect.','original'),
('127.818.d.9.E',3,'An operator switches on the main power to the mill, waits for the screen to load and then clears the alarms before homing the machine. She is performing:','["a power up on a standard CNC mill", "a shutdown", "a reboot of a phone", "a break"]'::jsonb,0,'CNC mill power-up.','original'),
('127.818.d.9.E',4,'The homing routine on a CNC mill is run to:','["clean the chips", "establish the machine''s reference position", "speed up the spindle", "change tools"]'::jsonb,1,'Homing sets machine zero.','original'),
('127.818.d.9.F',3,'A student uses the jog dial on the pendant to move the table in X and Y until the cutter sits just above the corner of the part. She is demonstrating:','["a board game", "a video game", "the use of jog controls on a CNC mill", "a map reading"]'::jsonb,2,'Jog controls position axes.','original'),
('127.818.d.9.F',4,'The Z axis on a vertical mill is the axis that moves:','["the table left to right", "the table front to back", "the vise open", "the spindle up and down"]'::jsonb,3,'Z is vertical.','original'),
('127.818.d.9.G',3,'A student assembles an end mill in a collet, sets it to the right stickout and measures its length on a presetter before loading it. She is demonstrating the ability to:','["locate, assemble and measure tooling for a CNC mill", "paint tools", "hide tools", "bend tools"]'::jsonb,0,'Preparing mill tooling.','original'),
('127.818.d.9.G',4,'A tool presetter is used to:','["paint the tool", "measure a tool''s length and diameter off the machine", "clean the coolant", "cool the spindle"]'::jsonb,1,'Presetters save machine time.','original'),
('127.818.d.9.H',3,'A student loads each cutter into its numbered pocket in the tool magazine so each matches the T number in the program. She is:','["oiling the vise", "painting the magazine", "installing tools and holders in the automatic tool changer locations of a CNC mill", "cleaning the floor"]'::jsonb,2,'Match tool numbers.','original'),
('127.818.d.9.H',4,'If tool 5 in the program is loaded in pocket 6 of the magazine, the likely result is that:','["the part is shinier", "the machine runs faster", "the cycle ends early", "the wrong tool will be used"]'::jsonb,3,'Mismatch causes errors.','original'),
('127.818.d.9.I',3,'A student uses an edge finder to locate the left and front edges of a plate in the vise and sets those as X zero and Y zero. She is:','["locating and setting a workpiece to zero on a CNC mill", "setting a timer", "setting a clock", "setting a table"]'::jsonb,0,'Edge finding sets XY zero.','original'),
('127.818.d.9.I',4,'An edge finder helps an operator to:','["measure a thread", "locate the edge of a part to set zero", "clean the vise", "cool the cutter"]'::jsonb,1,'It finds edges.','original'),
('127.818.d.9.J',3,'After finding the part edges, the student enters the X, Y and Z values into G54 so the program works from the part''s zero. She is setting:','["pay offsets", "table offsets", "work offsets for the part to be machined", "room offsets"]'::jsonb,2,'Work offsets locate the part.','original'),
('127.818.d.9.J',4,'Using G55 instead of G54 in a program means the control uses:','["a different coolant", "a different spindle", "a different cutter", "a different stored work offset"]'::jsonb,3,'Work offsets G54–G59.','original'),
('127.818.d.9.K',3,'For each end mill, drill and face mill in the magazine, the student enters its length and diameter offsets in the tool table. She is setting:','["the proper geometry/tool offsets for each tool in a standard tool-changer", "a poem", "a recipe", "a quilt"]'::jsonb,0,'Tool offsets per tool.','original'),
('127.818.d.9.K',4,'If a mill''s tool length offset is too short, the tool will:','["cut too deep always", "stop above the part and cut too shallow", "skip the program", "cut perfectly"]'::jsonb,1,'Offset affects Z depth.','original'),
('127.818.d.9.L',3,'After single-block proving, the operator closes the door and presses cycle start to let the mill run the entire program on its own. She is operating:','["a microwave", "a camera", "a CNC mill in automatic mode", "a blender"]'::jsonb,2,'Automatic mode runs the program.','original'),
('127.818.d.9.L',4,'While a mill runs a new program in automatic mode, the operator should keep a hand near the:','["coolant tank", "door latch only", "tool rack", "feed hold or emergency stop"]'::jsonb,3,'Be ready to stop.','original'),
('127.818.d.9.M',3,'At the end of the day the student parks the table, cleans the chips, powers off the control and then turns off the main disconnect. She is illustrating:','["the proper power down process on a CNC mill", "a restart", "a power up", "a standby"]'::jsonb,0,'Proper shutdown.','original'),
('127.818.d.9.M',4,'Before powering down a CNC mill, the operator should:','["remove the guards", "clean the machine and move the axes to a safe position", "leave chips in place", "unplug it mid-cycle"]'::jsonb,1,'Clean and park.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_115_v1'
from (values
('127.818.d.10.A',3,'A programmer uses the sine and cosine of a 30-degree chamfer to figure out the X and Z end points of a turned taper from the print. She is calculating:','["a budget", "a recipe", "trigonometry to determine coordinates from technical drawings for a CNC lathe", "a schedule"]'::jsonb,2,'Trig finds coordinates not dimensioned.','original'),
('127.818.d.10.A',4,'A 45-degree chamfer on a turned shoulder spans a set distance along the Z axis. Its change in X on the radius is:','["zero", "half of its Z length", "twice its Z length", "the same as its Z length"]'::jsonb,3,'At 45 degrees, rise equals run.','original'),
('127.818.d.10.B',3,'A programmer shifts the path of a round-nose tool using the tool''s nose radius and the cutting angle so the finished surface comes out on size. She is using:','["trigonometry for determining cutter offsets", "guessing", "a coin flip", "art techniques"]'::jsonb,0,'Offsets use trig.','original'),
('127.818.d.10.B',4,'Tool nose radius compensation is used on a lathe to:','["speed up the spindle", "correct for the rounded tip of the cutting insert", "cool the part", "clear chips"]'::jsonb,1,'Compensates for the radius.','original'),
('127.818.d.10.C',3,'A programmer calculates the spindle speed in RPM from the cutting speed and the part diameter, and the feed per revolution from the chip load. She is using:','["no math", "only memory", "appropriate mathematical skills to solve problems while programming a CNC lathe", "guesses"]'::jsonb,2,'Math supports programming.','original'),
('127.818.d.10.C',4,'For a constant surface speed on a lathe, as the diameter gets smaller the RPM must:','["stay the same", "decrease", "go to zero", "increase"]'::jsonb,3,'RPM = CS / diameter.','original'),
('127.818.d.10.D',3,'A student writes a short program that faces the end of a bar, then turns a 1-inch diameter for 2 inches at a set feed. She is writing:','["a simple program to face and turn", "a letter", "a story", "a poem"]'::jsonb,0,'Face and turn program.','original'),
('127.818.d.10.D',4,'In a lathe program, a facing pass is typically made by moving the tool along:','["the Y axis", "the X axis toward the centerline", "the spindle", "the Z axis only"]'::jsonb,1,'Facing moves in X.','original'),
('127.818.d.10.E',3,'A student adds G02 and G03 moves to cut a radius, a taper, a groove and a G76 thread to the end of her turning program. She is writing:','["a quote", "a song", "a simple program to cut radiuses, angles, grooves and threads", "a menu"]'::jsonb,2,'Contour and threading programs.','original'),
('127.818.d.10.E',4,'G02 and G03 in a CNC program command:','["tool changes", "spindle stops", "coolant on and off", "clockwise and counterclockwise arc moves"]'::jsonb,3,'Circular interpolation.','original'),
('127.818.d.10.F',3,'A programmer activates G41 so the control shifts the tool path to the left by the tool''s radius when finishing a contour. She is writing:','["a program using cutter radius compensation", "a cooking recipe", "a program without offsets", "a paper plan"]'::jsonb,0,'CRC shifts the path.','original'),
('127.818.d.10.F',4,'Cutter radius compensation lets the programmer:','["ignore the print", "program the part''s profile instead of the tool''s center", "use no offsets", "skip the tool"]'::jsonb,1,'Program part geometry.','original'),
('127.818.d.10.G',3,'Instead of writing every roughing pass by hand, a programmer calls a G71 cycle with a start and end for the contour and a depth of cut. She is writing:','["a list of random numbers", "a mailing", "a program using canned cycles such as G71", "a shopping list"]'::jsonb,2,'Canned cycles shorten programs.','original'),
('127.818.d.10.G',4,'A G71 canned cycle on a lathe is used to:','["stop the spindle", "change tools", "start coolant", "rough out a profile with repeated passes"]'::jsonb,3,'G71 is a stock removal cycle.','original'),
('127.818.d.10.H',3,'A student writes a full program for a complex NIMS Level 1 turned part with faces, diameters, radiuses and threads and then machines it. She is writing:','["a program and producing a complex part such as a NIMS Level 1 CNC turning project", "a note", "a doodle", "a poster"]'::jsonb,0,'Complete CNC turning project.','original'),
('127.818.d.10.H',4,'Before running a new complex program on a lathe, a good practice is to:','["remove the guard", "simulate it and run it in single-block mode", "skip the simulation", "run it blind at full speed"]'::jsonb,1,'Prove out new programs.','original'),
('127.818.d.11.A',3,'A programmer uses trigonometry to find the XY coordinates of the holes on a 3-inch bolt circle at 60-degree spacing for a mill program. She is using:','["a map", "a wish", "trigonometry to determine coordinates from technical drawings for a CNC mill", "a coin toss"]'::jsonb,2,'Trig finds hole positions.','original'),
('127.818.d.11.A',4,'For holes spaced every 60 degrees around a bolt circle, the number of holes is:','["5", "8", "4", "6"]'::jsonb,3,'360 ÷ 60 = 6.','original'),
('127.818.d.11.B',3,'A programmer calculates how far to shift a cutter path along an angled wall so the part ends up the right size on a mill. She is using:','["trigonometry for determining cutter offsets on a mill", "art", "guessing", "a hunch"]'::jsonb,0,'Offsets use trig.','original'),
('127.818.d.11.B',4,'The distance a cutter''s center must stay from a finished wall equals:','["the cutter diameter", "the cutter radius", "the part width", "zero"]'::jsonb,1,'Center is a radius away.','original'),
('127.818.d.11.C',3,'A programmer computes the RPM for a 3/4-inch end mill in aluminum and the feed rate from the chip load and number of flutes. She is using:','["only memory", "only guesses", "appropriate mathematical skills to solve problems while programming a CNC mill", "no math"]'::jsonb,2,'Math supports programming.','original'),
('127.818.d.11.C',4,'The feed rate for an end mill is found by multiplying:','["diameter by length", "RPM by diameter", "depth by width", "RPM by chip load per tooth by number of teeth"]'::jsonb,3,'IPM = RPM × chip load × flutes.','original'),
('127.818.d.11.D',3,'A student writes a short mill program that spot drills, drills and taps four holes using a drilling cycle. She is writing:','["a simple program to perform hole operations", "a quiz", "a novel", "a letter"]'::jsonb,0,'Hole operations program.','original'),
('127.818.d.11.D',4,'A G81 canned cycle on a mill is used for:','["facing only", "drilling a hole in one pass to depth", "tapping only", "boring only"]'::jsonb,1,'G81 is a simple drilling cycle.','original'),
('127.818.d.11.E',3,'A student adds arcs and angled lines to her mill program so a corner has a 0.250-inch radius and an edge has a 30-degree bevel. She is writing:','["a menu", "a poem", "a simple program to cut radiuses and angles", "a recipe"]'::jsonb,2,'Contour programs include arcs.','original'),
('127.818.d.11.E',4,'A 0.250-inch radius on a corner can be programmed using:','["G54", "T1", "M08", "G02 or G03 arc commands"]'::jsonb,3,'Arc commands cut radii.','original'),
('127.818.d.11.F',3,'A programmer uses G41 to compensate for the cutter''s radius and enters the cutter in a smooth arc so it enters the cut without a dwell mark. She is writing:','["a program using cutter radius compensation and ramping", "a cooking recipe", "a paper plan", "a program with no offsets"]'::jsonb,0,'CRC and ramping.','original'),
('127.818.d.11.F',4,'Ramping into a cut, instead of plunging, helps to:','["increase tool wear", "reduce tool stress and give a smoother entry", "create more noise", "skip a pass"]'::jsonb,1,'Ramping is gentler.','original'),
('127.818.d.11.G',3,'A student writes the complete program for a NIMS Level 1 milled part with pockets, hole patterns and a profile and then machines it on a CNC mill. She is writing:','["a doodle", "a note", "a program and producing a complex part such as a NIMS Level 1 CNC milling project", "a quick poster"]'::jsonb,2,'Complete CNC milling project.','original'),
('127.818.d.11.G',4,'After a CNC mill finishes a complex part, the student verifies it by:','["guessing", "looking at it", "skipping the print", "inspecting the critical features against the print"]'::jsonb,3,'Inspect to print.','original'),
('127.818.d.12.A',3,'A quality engineer reviews a print that uses datums, flatness and position tolerances to see whether a part can be made and inspected. She is evaluating:','["engineering drawings using geometric dimensioning and tolerancing", "a restaurant menu", "a fruit label", "a bus route"]'::jsonb,0,'GD&T evaluation.','original'),
('127.818.d.12.A',4,'In GD&T, a datum is:','["a coolant type", "a reference feature from which measurements are made", "a type of cutter", "a machine speed"]'::jsonb,1,'Datums are references.','original'),
('127.818.d.12.B',3,'A class reads the ASME Y14.5M standard to learn what each symbol in a feature control frame means. They are discussing:','["a sports rulebook", "a cooking guide", "the American Society of Mechanical Engineers Y14.5M standard", "a travel brochure"]'::jsonb,2,'Y14.5 defines GD&T.','original'),
('127.818.d.12.B',4,'The ASME Y14.5 standard is used to:','["set shop hours", "set menus", "set prices", "define how geometric tolerances are shown and interpreted on drawings"]'::jsonb,3,'A common language for tolerances.','original'),
('127.818.d.12.C',3,'A student compares the principles of ISO 9001, Six Sigma and lean manufacturing to see how each helps a shop improve product quality. She is appraising:','["various quality control and management programs", "only fashion", "only sports", "only cooking"]'::jsonb,0,'Quality programs improve consistency.','original'),
('127.818.d.12.C',4,'A quality program such as Six Sigma is mainly aimed at:','["hiding errors", "reducing defects and variation in processes", "raising prices", "slowing work"]'::jsonb,1,'Six Sigma reduces variation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
